  FT["PH-H6473"] = {"id":"PH-H6473","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7994_1995.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":"设立Sto市","en":"An Act Converting the Balagunan Barangay High School in the Municipality of Sto. Tomas, Province of Davao, Into a National High School to Be Known as the Balagunan National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Balagunan Barangay High School in the Municipality of Sto. Tomas, Province of Davao, Into a National High School to Be Known as the Balagunan National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7994","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7994_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6473-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Balagunan Barangay High School in the Municipality of Sto. Tomas, Province of Davao, is converted into a national high school to be known as the Balagunan National High School."}},{"id":"PH-H6473-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6473-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect immediately upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6474"] = {"id":"PH-H6474","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7995_1995.html","fetchedAt":"2026-10-06","articleCount":7,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Conversion of the Barotac Nuevo National Comprehensive High School in the Municipality of Barotac Nuevo, Province of Iloilo, Into a Polytechnic Institute to Be Known as the Barotac Nuevo Polytechnic Institute and Appropriating Funds Therefor","orig":"An Act Providing for the Conversion of the Barotac Nuevo National Comprehensive High School in the Municipality of Barotac Nuevo, Province of Iloilo, Into a Polytechnic Institute to Be Known as the Barotac Nuevo Polytechnic Institute and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7995","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 7 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7995_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6474-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Barotac Nuevo National High School in the Municipality of Barotac Nuevo, Province of Iloilo, is hereby converted into a polytechnic institute to be known as the Barotac Nuevo Polytechnic Institute."}},{"id":"PH-H6474-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The school, in addition to its present secondary offerings, is hereby authorized to offer post secondary programs in agriculture, technology and engineering and teacher education, which are priority programs of the government schools as well as short-term technical and vocational courses, subject to the policies of the Department of Education, Culture and Sports."}},{"id":"PH-H6474-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The title to the assets and properties now under the name of Barotac Nuevo Comprehensive High School shall be changed to the Barotac Nuevo Polytechnic Institute, in accordance with existing laws, rules and regulations."}},{"id":"PH-H6474-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The faculty and employees of the Barotac Nuevo Comprehensive High School shall remain as such faculty and employees of the Institute: Provided, however, That those who may opt to retire shall be granted such benefits and privileges as may be provided by existing laws."}},{"id":"PH-H6474-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Secretary of Education, Culture and Sports is hereby authorized to promulgate the necessary rules and regulations to implement the conversion and operation of the Institute subject to existing rules and regulations."}},{"id":"PH-H6474-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriation of the Barotac Nuevo National Comprehensive High School.\nThereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6474-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6475"] = {"id":"PH-H6475","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7996_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring the Asinan Area, the Las PiÃ±as Church and Bamboo Organ, the Las PiÃ±as Bridge, the Father Diego Cera Bridge, and the Old District Hospital, All in the Municipality of Las PiÃ±as, Metro Manila, as Tourist Spots","orig":"An Act Declaring the Asinan Area, the Las PiÃ±as Church and Bamboo Organ, the Las PiÃ±as Bridge, the Father Diego Cera Bridge, and the Old District Hospital, All in the Municipality of Las PiÃ±as, Metro Manila, as Tourist Spots"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 7996","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7996_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6475-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Dr. Gerardo Sabal Memorial Municipal High School in the Poblacion, Municipality of Claveria, Province of Misamis Oriental, is hereby converted into a national high school to be known as the Dr. Gerardo Sabal Memorial National High School."}},{"id":"PH-H6475-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations and guidelines as may be necessary to carry out the purposes of this Act."}},{"id":"PH-H6475-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6475-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6476"] = {"id":"PH-H6476","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7997_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Burauen市","en":"An Act Converting the Burauen National High School in Sto. Niño, Municipality of Burauen, Province of Leyte, Into a Comprehensive National High School to Be Known as the Burauen Comprehensive National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Burauen National High School in Sto. Niño, Municipality of Burauen, Province of Leyte, Into a Comprehensive National High School to Be Known as the Burauen Comprehensive National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 7997","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7997_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6476-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Burauen National High School in Sto. Ni-o, Municipality of Burauen, Province of Leyte, is hereby converted into a national comprehensive high school to be known as the Burauen Comprehensive National High School."}},{"id":"PH-H6476-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6476-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, assets, liabilities, and records of the Burauen National High School are hereby transferred to and absorbed by the Burauen Comprehensive National High School."}},{"id":"PH-H6476-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Burauen National High School in Sto. Ni-o, Burauen, Leyte. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6476-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6477"] = {"id":"PH-H6477","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7998_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Minglanilla市","en":"An Act Converting the Tubod Barangay High School in the Municipality of Minglanilla, Province of Cebu, Into a National High School, to Be Known as the Tubod National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Tubod Barangay High School in the Municipality of Minglanilla, Province of Cebu, Into a National High School, to Be Known as the Tubod National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 7998","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7998_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6477-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tubod Barangay High School in the Municipality of Minglanilla, Province of Cebu, is hereby converted into a national high school, to be known as the Tubod National High School."}},{"id":"PH-H6477-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6477-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6477-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6478"] = {"id":"PH-H6478","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_7999_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring a Total of One Hundred Twenty (120) Hectares of the Tala Estate, Kalookan City as Alienable and Disposable and Converting Them Into Housing Sites, Amending for This Purpose Certain Sections of Presidential Proclamation No. 843, and for Other Purposes","orig":"An Act Declaring a Total of One Hundred Twenty (120) Hectares of the Tala Estate, Kalookan City as Alienable and Disposable and Converting Them Into Housing Sites, Amending for This Purpose Certain Sections of Presidential Proclamation No. 843, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 7999","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_7999_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6478-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Declaration of a Total of One Hundred Twenty (120) Hectares of the Tala Estate as Alienable and Disposable and their Conversion into Housing Sites. - Of the eight hundred eight (808) hectares of the Tala Estate located in Kalookan City which were reserved under Presidential Proclamation No. 843 for Tala Leprosarium and settlement site for hansenites and their families; a pilot housing development project; a civic center; welfare projects; and for other housing and urban development purposes, the following areas are hereby declared and/or converted as follows:\na. Seventy (70) hectares of the one hundred thirty (130) hectares reserved for the leprosarium and settlement site of the hansenites and their families under Proclamation No. 843 are hereby declared alienable and disposable for use as a housing site for the bona fide residents, hansenites and their immediate families and for qualified employees of the Department of Health: Provided, That if the said beneficiary is an employee of the Department of Health, the said employee must have been assigned in the Tala Leprosarium and must have been a resident thereat for at least five (5) years: Provided, further, That the residential lot awarded to the beneficiaries under this Act shall not be transferred, conveyed or assigned to any other person for a period of twenty-five (25) years, except to legal heirs by way of succession; and\nb. The fifty (50) hectares reserved for the plants, installations and pilot housing project of the National Housing Corporation, as provided in the same proclamation, are hereby declared as alienable and disposable: Provided, That twenty-nine (29) hectares of the said fifty (50) hectares shall be converted into a housing site exclusively for the bona fide and qualified residents of the area."}},{"id":"PH-H6478-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Implementing Agency. - The National Housing Authority shall be the agency primarily responsible for the implementation and enforcement of this Act.\nThe National Housing Authority, in cooperation with the Department of Health and in consultation with the homeowners associations concerned, shall promulgate and issue such rules and regulations for the effective implementation and enforcement of the provisions of this Act, subject to existing policies on cost recovery, housing planning and development and other existing laws."}},{"id":"PH-H6478-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"AdHoc Committee. - An ad hoc committee of seven (7) members composed of representatives of the National Housing Authority, the Department of Health, the Presidential Commission for the Urban Poor, the City Government of Kalookan, a nongovernment organization concerned with hansenites, an urban poor people's organization, and the hansenites associations shall be formed to issue the necessary guidelines to determine who are the qualified beneficiaries under this Act."}},{"id":"PH-H6478-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Repealing Clause. - Presidential Proclamation No. 843 and other laws, executive orders, proclamations and administrative rules and regulations inconsistent with the provisions of this Act are hereby repealed or modified accordingly."}},{"id":"PH-H6478-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days after the completion of its publication in at least two (2) newspapers of general circulation."}}],"pack":"ph-p92"};
  FT["PH-H6479"] = {"id":"PH-H6479","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8000_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Authorizing the Improvement and Development of the Ardent Spring in the Municipality of Mambajao, Province of Camiguin","orig":"An Act Authorizing the Improvement and Development of the Ardent Spring in the Municipality of Mambajao, Province of Camiguin"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8000","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8000_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6479-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ardent Spring in the Municipality of Mambajao, Province of Camiguin, shall hereby be improved and developed in order to enhance its tourism attraction and potentials."}},{"id":"PH-H6479-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government, shall prepare the development plan and construct the appropriate facilities and infrastructure for the area, subject to set tourism standards: Provided, That the development plan shall ensure the protection and preservation of the natural beauty and historical significance thereof."}},{"id":"PH-H6479-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development plan and incorporate the same in the Department's overall tourism development program for the ensuing calendar year."}},{"id":"PH-H6479-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall likewise promulgate the rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6479-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6480"] = {"id":"PH-H6480","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8001_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Providing for the Development of the Dalama Shoreline in the Municipality of Molundo, Province of Lanao Del Sur, Into a Public Beach Resort","orig":"An Act Providing for the Development of the Dalama Shoreline in the Municipality of Molundo, Province of Lanao Del Sur, Into a Public Beach Resort"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8001","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8001_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6480-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Dalama shoreline in the Municipality of Molundo, Province of Lanao del Sur, shall hereby be developed into a public beach resort."}},{"id":"PH-H6480-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government, shall prepare the development plan and construct the appropriate facilities and infrastructure for the area, subject to set tourism standards: Provided, That the development plan shall ensure the preservation of the natural beauty thereof."}},{"id":"PH-H6480-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development plan and incorporate the same in the Department's overall tourism development program for the ensuing calendar year."}},{"id":"PH-H6480-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall likewise promulgate the necessary rules and regulations for the effective implementation of this Act."}},{"id":"PH-H6480-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6481"] = {"id":"PH-H6481","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8002_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Palo市","en":"An Act Declaring the Site in the Municipality of Palo, Province of Leyte, Where General Douglas Macarthur Landed on October 20, 1944 to Liberate the Philippines During World War Ii, a Tourist Spot","orig":"An Act Declaring the Site in the Municipality of Palo, Province of Leyte, Where General Douglas Macarthur Landed on October 20, 1944 to Liberate the Philippines During World War Ii, a Tourist Spot"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8002","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8002_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6481-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The site in the Municipality of Palo, Province of Leyte, where General Douglas Mac Arthur landed on October 20, 1944 to liberate the Philippines during World War II, is hereby declared a tourist spot. As such, it shall be accorded priority development by the Department of Tourism and shall be subject to the rules and regulations governing the development of tourist spots."}},{"id":"PH-H6481-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government shall, within one (1) year from the approval of this Act, prepare a development plan involving the construction, installation and maintenance of such appropriate facilities and infrastructure as shall enhance tourism in the area: Provided, That said development plan shall ensure the preservation of the natural beauty and historical significance of the area."}},{"id":"PH-H6481-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development plan and shall incorporate the same in the Department's overall tourism development program for the ensuing calendar year."}},{"id":"PH-H6481-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall promulgate the necessary rules and regulations for the proper implementation of this Act."}},{"id":"PH-H6481-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6482"] = {"id":"PH-H6482","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8003_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring the Asinan Area, the Las PiÃ±as Church and Bamboo Organ, the Las PiÃ±as Bridge, the Father Diego Cera Bridge, and the Old District Hospital, All in the Municipality of Las PiÃ±as, Metro Manila, as Tourist Spots","orig":"An Act Declaring the Asinan Area, the Las PiÃ±as Church and Bamboo Organ, the Las PiÃ±as Bridge, the Father Diego Cera Bridge, and the Old District Hospital, All in the Municipality of Las PiÃ±as, Metro Manila, as Tourist Spots"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 8003","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-22","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8003_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6482-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Asinan Area, the Las Piñas Church and Bamboo Organ, the Las Piñas Bridge, the Father Diego Cera Bridge, and the old district hospital, all in the Municipality of Las Piñas, Metro Manila, are hereby declared tourist spots. As such, they shall be accorded priority development by the Department of Tourism, subject to the rules and regulations governing the development of tourist spots."}},{"id":"PH-H6482-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government shall, within one (1) year from the approval of this Act, prepare a development plan involving the construction, installation and maintenance of such appropriate facilities and infrastructure as shall enhance tourism in said areas: Provided, That said development plan shall ensure the preservation of the natural beauty and historical significance of the areas."}},{"id":"PH-H6482-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development plan and shall incorporate the same in the Department's overall tourism development program for the year following the approval of this Act."}},{"id":"PH-H6482-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall promulgate the necessary rules and regulations for the proper implementation of this Act."}},{"id":"PH-H6482-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6483"] = {"id":"PH-H6483","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8004_1995.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting to Millennia Telecommunications Corporation a Franchise to Install, Operate and Maintain Telecommunications Services Within the Philippines and International Points, and for Other Purposes","orig":"An Act Granting to Millennia Telecommunications Corporation a Franchise to Install, Operate and Maintain Telecommunications Services Within the Philippines and International Points, and for Other Purposes"},"level":"law","status":"active","topics":["investment","data"],"docNumber":"Republic Act No. 8004","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-04-27","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8004_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6483-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the conditions established in this Act and the provisions of the Constitution and the provisions of laws, orders or issuances not inconsistent herewith, there is hereby granted to Millennia Telecommunications Corporation, its successors or assigns the right, privilege, and authority to construct, operate and maintain all types of mobile telecommunications including cellular, personal communications network, paging and trunk radio services (such as but not limited to the transmission and reception of voice, data facsimile, audio and video, and all other improvements and innovations pertaining to or as may be applicable to mobile telecommunications technology), as well as multi-channel microwave, fiber optic and satellite distribution systems that may be required for purposes of linking together said mobile telecommunications network internally and externally to other mobile telecommunications network and traditional wireline telephone systems whether domestic or international, whether directly or indirectly through networks, and generally, to provide, by means of this telecommunications systems, a telephone service and such other telecommunications services such as there may be in demand for in the Philippines."}},{"id":"PH-H6483-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The President of the Philippines in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace may take over and operate the transmitting, receiving, and switching stations of the grantee or to authorize the temporary use and operation thereof by any department of the Government upon the compensation to the grantee for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6483-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The grantee may install, operate and maintain radio telecommunications systems to provide a telephone service and other telecommunications services including mobile services within the territory of the Republic of the Philippines and between the Republic of the Philippines and ships at sea, aircraft in the air, and the telecommunications systems of other countries: Provided, That the location, installation or operation of any such radio telecommunication system must be previously approved by the National Telecommunications Commission (NTC): Provided, further, That the National Telecommunications Commission shall have the authority to supervise and regulate the installation or operation of such radio telecommunication system."}},{"id":"PH-H6483-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"For the purpose of installing, operating and maintaining its telecommunication lines, it shall be lawful for the grantee, its successors or assigns, to make excavations or lay conduits in any of the public places, highways, streets, lanes, alleys, avenues, sidewalks, bridges of said provinces, cities, and municipalities: Provided, however, That any public place, highways, street, lane, alley, avenue, sidewalk or bridge disturbed, altered or changed by reason of the installation, operation and maintenance of said telecommunications lines underground shall be repaired and replaced in a workmanlike manner by said grantee, its successors or assigns to the satisfaction of the National Telecommunications Commission. Should the grantee, its successors or assigns, after thirty (30) days notice from proper authority, fail, refuse, or neglect to repair or replace any part of a public place, road, highway, street, lane, alley, avenue, sidewalk or bridge altered, changed, or disturbed by said grantee, its successors or assigns, then they shall have the right to have the same repaired and placed in good order and condition at the cost and expense of the grantee, its successors and assigns."}},{"id":"PH-H6483-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This franchise shall be for a term of twenty-five (25) years from the date of effectivity of this Act, unless sooner revoked or cancelled. In the event that the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6483-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Acceptance of this franchise shall be given in writing within sixty (60) days after the approval of this Act. The grantee shall operate the telecommunications systems for which this franchise is granted within four (4) years from the date of its acceptance in writing of this franchise. Refusal or failure to accept the franchise or to operate within the prescribed period shall render the franchise void."}},{"id":"PH-H6483-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All telecommunications systems owned, operated or maintained by the grantee, its successors or assigns, shall be operated and maintained at all times in a satisfactory manner, and it shall be the further duty of said grantee, its successors or assigns, whenever required to do so by the National Telecommunications Commission, to modify, improve and change such telecommunication systems, in such manner and to such extent as the progress of science and improvements in the method of conveyance of telecommunications messages by means of said systems may make reasonable, proper and economically feasible."}},{"id":"PH-H6483-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee, its successors or assigns, shall keep a separate account of the gross receipts of the telecommunications service business transacted by it and shall furnish to the Commission on Audit and the National Treasurer a copy of such account not later than the thirty-first of January of each year for the preceding twelve (12) months."}},{"id":"PH-H6483-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The grantee shall not exercise any right or privilege under this franchise without first having obtained such certificate of public necessity and convenience from the National Telecommunications Commission. This franchise shall not take effect nor shall any power be exercised by the grantee until the National Telecommunications Commission shall have allotted to the grantee the frequencies and wavelengths to be used and determined the stations to and from which each frequency and wavelength may be used, and issued to the grantee a license for such use."}},{"id":"PH-H6483-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The stations of the grantee shall be so constructed and operated and the wavelengths so elected as to avoid interference with existing stations and to permit the expansion of the grantee's services."}},{"id":"PH-H6483-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceedings and just compensation paid or tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use, or occupation of any land except such as is required for the actual and necessary purposes for which this franchise is granted."}},{"id":"PH-H6483-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"As a guaranty that this franchise has been accepted in good faith, the grantee, its successors or assigns, shall file, after the granting of the certificate of public necessity and convenience by the National Telecommunications Commission, with the National Treasurer, a surety bond in such amount as may be fixed by the proper government authority to guarantee full compliance and fulfillment of the conditions under which this franchise is granted.\nShould the said grantee, its successors or assigns for any cause other than the act of God, the public enemy, usurped or military power, martial law, riot, civil commotion, or inevitable cause, fail, refuse, or neglect to begin, within two (2) years from the date of the granting of said certificate of public necessity and convenience, the business of providing telecommunication service or fail, refuse, or neglect to be fully equipped and ready to operate, within two (2) years from the date of granting of said certificate of public necessity and convenience, telecommunications systems as have been agreed with competent authority, according to the terms of this franchise, then the bond prescribed by this section to be filed with the National Treasurer shall become the property of the National Government as liquidated damages caused to the Government by such failure, refusal or neglect, and thereafter no interest on said bonds shall be paid to the grantee, its successors or assigns.\nShould the grantee, its successors or assigns, begin the business of providing a telephone service and be ready to operate according to the terms of this franchise, telecommunications systems within two (2) years from the date of the granting of said certificate of public necessity and convenience, then and in that event the bond prescribed by this section shall be returned by the Government of the grantee, its successors or assigns, as soon as the telephone service has begun in accordance with the terms of this franchise: Provided, further, That all the time during which the grantee, its successors or assign, may be prevented from carrying out the terms and conditions of this franchise by any of said causes shall be added to the time allowed by this franchise for compliance with its provisions."}},{"id":"PH-H6483-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"The grantee, its successors or assigns shall be liable to pay the same taxes on its real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations which are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall be levied, assessed and collected a franchise tax equivalent to three percent (3%) of all gross receipts of the business transacted under this franchise by the grantee, its successors or assigns, and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code.\nThe grantee shall file the return with, and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative in accordance with the National Internal Revenue Code. The return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6483-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The rates for the telephone service or charges for every type of call, flat rates as well as measured rates, are subject to the approval of the National Telecommunications Commission."}},{"id":"PH-H6483-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The grantee is authorized to connect its telecommunications systems to any other telecommunication system installed, operated and maintained by any other grantee in the Philippines for the purpose of providing telecommunications services to the public on such terms and conditions as may be prescribed from time to time by the Secretary of Transportation and Communications."}},{"id":"PH-H6483-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The books and accounts of the grantee, its successors or assigns, shall always be open to the inspection of the Commissioner on Audit or his authorized representatives, and it shall be the duty of the grantee to submit to the Commission on Audit quarterly reports in duplicate showing the gross receipts and the net receipts for the quarter past and the general condition of the business."}},{"id":"PH-H6483-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The rights herein granted shall not be exclusive, and the rights and power to grant to any corporation, association, or person other than the grantee, a franchise for the provision of telephone service or the installation, operation and maintenance of a telecommunications systems grant subsequent to this franchise shall be so placed as not to impair the efficient and effective operation of the telecommunications systems installed under this franchise and actually in existence at the time of the granting of said subsequent franchise: Provided, further, That the National Telecommunications Commission after hearing both parties interested, may compel the grantee of this franchise or its successors or assigns, to remove, relocate, or replace its telecommunication lines but in such case the reasonable cost of the removal, relocation, or replacement shall be paid by the grantee of this franchise or its successors or assigns."}},{"id":"PH-H6483-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or entity, nor merge with any other corporation or entity without the prior approval of the Congress of the Philippines. Neither shall the controlling interest in the grantee be transferred, whether as a whole or in parts and whether simultaneously or contemporaneously, to any such person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines, except when the transfer is done: (a) through a stock exchange transaction; (b) for purposes of qualifying persons for election to the board; and (c) to a corporation that is controlled by the same stockholders as that of the grantee. Any person or entity to which this franchise is validly sold, transferred or assigned shall be subject to all the same conditions, terms, restrictions and limitations of this Act."}},{"id":"PH-H6483-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"In compliance with the constitutional mandate to democratize ownership of public utilities, the herein grantee shall make a public offering through the stock exchange of at least thirty percent (30%) of its common stocks within a period of three (3) years from the date of the effectivity of this Act: Provided, That no single person or entity shall be allowed to own more than five percent (5%) of the stock offering."}},{"id":"PH-H6483-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"The grantee is authorized to contract the installation and operation of the telecommunications system which is the subject of this grant, to private entities with expertise in the field of telecommunications under such terms and conditions as may be approved by the National Telecommunications Commission."}},{"id":"PH-H6483-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"This franchise is granted with the understanding and upon the condition that it shall be subject to amendment, alteration or repeal by the Congress as provided in the Constitution, and that all lands or rights or use or occupation of lands secured by virtue of this franchise shall revert upon its termination to the national, provincial, city or municipal governments which were the owners thereof upon the date on which this franchise was granted. The pertinent provisions of the Constitution are hereby incorporated in and made part of these presents, with the same effect as if they were expressed herein."}},{"id":"PH-H6483-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"This Act shall take effect fifteen (15) days after its publication in two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p92"};
  FT["PH-H6484"] = {"id":"PH-H6484","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8005_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Ajuy市","en":"An Act Converting the Ajuy National High School in the Municipality of Ajuy, Province of Iloilo, Into a Polytechnic College to Be Known as the Ajuy Polytechnic College","orig":"An Act Converting the Ajuy National High School in the Municipality of Ajuy, Province of Iloilo, Into a Polytechnic College to Be Known as the Ajuy Polytechnic College"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8005","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-07","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8005_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6484-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Ajuy National High School in the Municipality of Ajuy, Province of Iloilo, is hereby converted into a polytechnic college to be known as the Ajuy Polytechnic College."}},{"id":"PH-H6484-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The faculty and employees of the Ajuy National High School, as well as its funds, assets, equipment and facilities shall be absorbed by the college."}},{"id":"PH-H6484-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Commission on Higher Education is hereby directed to take such steps as are necessary for the immediate conversion and operation of the college."}},{"id":"PH-H6484-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of Ajuy National High School. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6484-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6485"] = {"id":"PH-H6485","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8006_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Perez市","en":"An Act Converting the Perez Quezon Academy in the Municipality of Perez, Quezon Province, Into a National High School to Be Known as the Perez National High School, and Appropriating Funds Therefor","orig":"An Act Converting the Perez Quezon Academy in the Municipality of Perez, Quezon Province, Into a National High School to Be Known as the Perez National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8006","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-18","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8006_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6485-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Perez Quezon Academy, a secondary school in the Municipality of Perez, Quezon Province, is hereby converted into a national high school to be known as the Perez National High School."}},{"id":"PH-H6485-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6485-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, assets, liabilities, and records of the Perez Quezon Academy are hereby transferred to and absorbed by the Perez National High School."}},{"id":"PH-H6485-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6485-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6486"] = {"id":"PH-H6486","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8007_1995.html","fetchedAt":"2026-10-06","articleCount":22,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Converting the Mindoro College of Agriculture and Technology Into a State College, Providing a Charter for This Purpose, Expanding Its Curricular Offerings, Redirecting Its Objectives, and Appropriating Funds Thereof","orig":"An Act Converting the Mindoro College of Agriculture and Technology Into a State College, Providing a Charter for This Purpose, Expanding Its Curricular Offerings, Redirecting Its Objectives, and Appropriating Funds Thereof"},"level":"law","status":"active","topics":["education","environment","culture"],"docNumber":"Republic Act No. 8007","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 22 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8007_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6486-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The present Mindoro College of Agriculture and Technology in the Municipality of Victoria, Oriental Mindoro, is hereby converted into a state college, hereinafter referred to as the State College."}},{"id":"PH-H6486-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The State College shall primarily provide higher vocational, professional and technical instruction and training in agricultural and industrial fields with special emphasis given to agricultural industry. It shall also promote research, advanced studies and progressive leadership in the fields of agriculture, including agricultural education and home technology, with special emphasis given to agricultural industry, fishery, forestry, and industrial education."}},{"id":"PH-H6486-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"In addition to its present secondary agricultural course and undergraduate courses leading to the degrees of bachelor of science in agriculture and bachelor of science in agricultural education, the State College shall offer undergraduate courses leading to the degrees of bachelor of science in food technology, bachelor of science in nutrition, bachelor of science in home technology, bachelor of science in agricultural technology, bachelor of science in agricultural engineering, and bachelor of science in elementary agriculture; courses in fresh-water fish culture, processing of agricultural products and such other degrees, courses and special courses as the Board of Trustees may deem necessary. It shall also offer opportunity for short-term technical or vocational courses within its areas of specialization to meet the needs of the island provinces of Oriental Mindoro and Occidental Mindoro."}},{"id":"PH-H6486-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"No student shall be denied admission to the State College by reason of age, ethnic consideration, or religious belief or affiliation."}},{"id":"PH-H6486-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The head of the State College shall be known as the President of the Mindoro College of Agriculture and Technology. He shall be appointed by the President of the Philippines upon the recommendation of the Board of Trustees.\nHis salary shall be comparable to that being received by presidents of similar educational institutions of like enrollment and standing, subject to the provisions of the revised compensation and position classification system.\nThe duties and powers of the President of the State College, in addition to those specifically provided for in this Act, shall be those usually pertaining to the office of the president of a state college or university."}},{"id":"PH-H6486-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The governing body of the State College shall be the Board of Trustees of the Mindoro College of Agriculture and Technology. It shall be composed of the chairperson of the Commission on Higher Education (CHED), who shall be the chairman, the Director of Agricultural Training Institute, the Dean of the University of the Philippines College of Agriculture in Los Ba-os, the President of the State College, and four (4) prominent citizens of Region IV to be appointed by the President of the Philippines, as members.\nOf the four appointed members, one shall be an authority on agriculture, one on science, one on arts and trades, and one on technology: Provided, That at least one of the four appointed members shall be a citizen of Oriental Mindoro, if not an alumnus of the Mindoro College of Agriculture and Technology. Of the first group appointed, the President shall designate one to serve for one (1) year; one to serve for two (2) years; one to serve for three (3) years; and the other to serve for four (4) years. Thereafter, persons appointed to succeed such members shall hold office for a term of four (4) years and until their successors shall have been appointed and qualified. In case of permanent vacancy, the position shall be filled by appointment by the President of the Philippines. Such appointee shall hold office for the unexpired term only.\nWhen the chairperson of the CHED is unable to perform his duties as chairman of the Board due to illness, absence or other cause, or in case of a vacancy in the office, any commissioner of the CHED shall temporarily perform the functions of the chairman of the said Board. The chairman may assign qualified officials to represent him with full authority in the Board."}},{"id":"PH-H6486-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"A quorum of the Board of Trustees shall consist of a majority of all members holding office at the time a meeting is called. All processes against the Board of Trustees shall be served on the president or the secretary thereof."}},{"id":"PH-H6486-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The members of the Board of Trustees shall not receive salary but shall be entitled to reimbursement for actual and necessary expenses incurred either in attendance upon meetings of the Board or upon other official business authorized by resolution of the Board, subject to existing budget laws, rules and regulations on honoraria and allowances."}},{"id":"PH-H6486-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The Board of Trustees shall have the following powers and duties in addition to its general powers of administration, and the exercise of all powers of a corporation as provided in Section 13 of Act No. 1459, as amended, otherwise known as the corporation law:\na. To receive and appropriate for the purposes specified by law such sums as may be provided for the support of the State College;\nb. To confer degrees upon successful candidates for graduation of the State College. It may also confer honorary degrees upon persons in recognition of learning, statesmanship or eminence in any of the fields of specialization of the State College, or in recognition of public service: Provided, That such degree shall not be conferred in consideration of or to reciprocate some personal favors;\nc. Subject to civil service law, rules and regulations, to appoint upon recommendation of the President of the State College, the deans of the different schools of the State College, the registrar, the heads of departments, professors, instructors, lecturers, and other employees of the State College; to fix their hours of service and such other duties and conditions as it may deem proper; to grant them, at its discretion, leaves of absence under such regulations as it may promulgate, any provisions of existing laws to the contrary notwithstanding; to remove them for cause after an investigation and hearing;\nd. To approve the curriculum and rules of discipline drawn by the State College council as hereinafter provided;\ne. To fix tuition fees, matriculation fees, graduation fees, laboratory fees, and other special fees;\nf. To provide fellowships for qualified faculty members and scholarships to deserving students;\ng. To prescribe rules for its government and to enact for the government of the State College such rules and regulations not contrary to law as may be necessary to carry out the purposes and functions of the State College;\nh. To receive in trust legacies, gifts and donations of real and personal property of all kinds, to administer the same for the benefit of the State College or the departments thereof, or for aid to any student or students in accordance with the direction and instructions of the donor, and in default thereof, in such manner as the Board of Trustees may in its discretion determine. All such donations shall be exempt from all taxes and be considered as deductible items from the income tax of the donor.\ni. To import duty-free commodities for educational purposes as an exception to existing laws;\nj. To provide vocational training to adult citizens and out-of-school youths;\nk. To name after prominent Filipinos or heroes any building, annex ground, or branch of the State College; and\nl. To authorize the State College to undertake construction and/or repair of its buildings, machineries and equipment and other facilities, any provision of law or executive order to the contrary notwithstanding: Provided, That the funds for the purpose shall come from its appropriation."}},{"id":"PH-H6486-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"On or before the fifteenth day of the second month after the opening of regular classes each year, the Board of Trustees shall file with the Office of the President of the Philippines a detailed report, setting forth the progress, conditions and needs of the State College."}},{"id":"PH-H6486-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"There shall be a State College council consisting of the President of the State College and all members of the faculty. The council shall have the power to prescribe the curriculum and rules of discipline, subject to the approval of the Board of Trustees. It shall fix the requirements for admission to the State College, as well as for graduation and conferring of degrees, subject to review by the Board of Trustees. The council alone shall have the power to recommend students or others to be recipients of degrees. Through the President of the State College or its duly authorized committee, the council shall have disciplinary power over the students within the limits prescribed by the rules of discipline."}},{"id":"PH-H6486-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"The body of instructors and professors of the State College shall constitute the faculty of the State College, with the President of the State College as the presiding officer."}},{"id":"PH-H6486-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"No member of the faculty of the State College shall attempt directly or indirectly, under penalty of dismissal by the Board of Trustees, to influence students or any person in the State College towards any ideology, political or otherwise, which preaches the overthrow of the government through violence or subversion."}},{"id":"PH-H6486-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"There shall be a secretary of the State College who shall be appointed by the Board of Trustees upon recommendation of the President of the State College. He shall also be the secretary of the Board and shall keep such records of the State College as may be determined by the Board of Trustees."}},{"id":"PH-H6486-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"The Treasurer of the Philippines shall be the ex officio treasurer of the State College and all accounts and expenses therefor shall be audited by the Commission on Audit or its duly authorized representatives and all disbursements shall be made in accordance with auditing rules and regulations."}},{"id":"PH-H6486-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"The heads of bureaus and offices of the national government are hereby authorized to loan or transfer, upon request of the President of the State College, such apparatus, equipment or supplies as may be needed by the State College and to detail employees for duty therein, when in the judgment of the head of the bureau or office such apparatus, equipment, supplies or services of such employees can be spared without serious detriment to the public service. The employees so detailed shall perform such duty as required of them under such detail and the time so employed shall be counted as part of their regular official service."}},{"id":"PH-H6486-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"The requirements provided in this Act as may prove adverse to the present faculty and employees of the State College who may be absorbed by virtue of this Act shall not apply to them. But future appointees to the State College shall be subject to all the requirements provided in this Act."}},{"id":"PH-H6486-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"All parcels of land, buildings, equipment, facilities, whether fixed or movable, personnel and records owned by the Mindoro College of Agriculture and Technology, as well as its obligations and appropriations thereof, shall be transferred to the State College."}},{"id":"PH-H6486-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"The amount needed to carry out the provisions of this Act shall be charged against the current year's appropriations of the Mindoro College of Agriculture and Technology. Thereafter, such sums as may be necessary for the continued operation and maintenance of the State College shall be included in the annual General Appropriations Act."}},{"id":"PH-H6486-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"The chairperson of the Commission on Higher Education is hereby directed to take steps as are necessary for the immediate implementation of this Act."}},{"id":"PH-H6486-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"All laws, decrees, executive orders contrary to or inconsistent with the provisions of this Act are hereby repealed or amended accordingly."}},{"id":"PH-H6486-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6487"] = {"id":"PH-H6487","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8008_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Magsaysay市","en":"An Act Converting the Danawan Nationalized High School in Barangay Danawan, Municipality of Magsaysay, Province of Palawan, Into the Danawan Science High School, and Appropriating Funds Therefor","orig":"An Act Converting the Danawan Nationalized High School in Barangay Danawan, Municipality of Magsaysay, Province of Palawan, Into the Danawan Science High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8008","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8008_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6487-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The existing Danawan Nationalized High School in Barangay Danawan, Municipality of Magsaysay, Province of Palawan, is hereby converted into a science high school to be known as the Danawan Science High School."}},{"id":"PH-H6487-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall promulgate the necessary rules and regulations for the implementation of this Act."}},{"id":"PH-H6487-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be charged against the current year's appropriations of the Danawan National High School. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6487-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6488"] = {"id":"PH-H6488","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8009_1995.html","fetchedAt":"2026-10-06","articleCount":8,"structureMode":"ARTICLE","title":{"zh":"设立Villaba市","en":"An Act Converting the Leyte National Agricultural College in the Municipality of Villaba, Province of Leyte, Into a College of Agriculture, Science and Technology to Be Known as the Leyte National College of Agriculture, Science and Technology, and Appropriating Funds Therefor","orig":"An Act Converting the Leyte National Agricultural College in the Municipality of Villaba, Province of Leyte, Into a College of Agriculture, Science and Technology to Be Known as the Leyte National College of Agriculture, Science and Technology, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education","environment","culture"],"docNumber":"Republic Act No. 8009","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 8 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8009_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6488-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Leyte National Agricultural College in the Municipality of Villaba, Province of Leyte, is hereby converted into a college of agriculture, science and technology to be known as the Leyte National College of Agriculture, Science and Technology."}},{"id":"PH-H6488-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In addition to its present secondary, post-secondary and degree curricular offerings, the Leyte National College of Agriculture, Science and Technology shall offer undergraduate courses in the fields of industrial education and technology, engineering, arts and sciences, forestry, veterinary, two-year technician courses in trade and agriculture, and such other short-term occupational courses as may be necessary to meet local and national needs for trained manpower."}},{"id":"PH-H6488-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"It shall grant proficiency certificates in non-degree courses and diplomas to degrees offered."}},{"id":"PH-H6488-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The College shall be under the direct supervision of the Commission on Higher Education and shall be headed by a vocational college superintendent."}},{"id":"PH-H6488-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Commission on Higher Education shall take the necessary steps for the immediate operationalization of the Leyte National College of Agriculture, Science and Technology and the implementation of the provisions of this Act."}},{"id":"PH-H6488-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the current year's appropriations of the Leyte National Agriculture College. Thereafter, such sums as may be necessary for its operation and maintenance shall be included in the annual General Appropriations Act."}},{"id":"PH-H6488-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"All laws, decrees, executive orders, rules, regulations and other issuances, or parts thereof, which are inconsistent with the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6488-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6489"] = {"id":"PH-H6489","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8010_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Binangonan市","en":"An Act Converting the Vicente Madrigal Municipal High School Into a National High School to Be Known as the Vicente Madrigal National High School in the Municipality of Binangonan, Province of Rizal, and Appropriating Funds Therefor","orig":"An Act Converting the Vicente Madrigal Municipal High School Into a National High School to Be Known as the Vicente Madrigal National High School in the Municipality of Binangonan, Province of Rizal, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8010","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8010_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6489-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Vicente Madrigal Municipal High School is hereby converted into a national high school to be known as the Vicente Madrigal National High School."}},{"id":"PH-H6489-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Secretary of the Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6489-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6489-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6490"] = {"id":"PH-H6490","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8011_1995.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Leyte State School of Arts and Trades in Tanauan, Leyte, to Leyte College of Arts and Trades","orig":"An Act Changing the Name of the Leyte State School of Arts and Trades in Tanauan, Leyte, to Leyte College of Arts and Trades"},"level":"law","status":"active","topics":["education","culture"],"docNumber":"Republic Act No. 8011","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8011_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6490-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Leyte State School of Arts and Trades in Tanauan, Leyte, is hereby changed to Leyte College of Arts and Trades."}},{"id":"PH-H6490-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Leyte College of Arts and Trades shall be under the supervision of the Commission on Higher Education."}},{"id":"PH-H6490-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6491"] = {"id":"PH-H6491","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8012_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Palawan National Agricultural College in the Municipality of Aborlan, Province of Palawan, to State Polytechnic College of Palawan and Authorizing the Same to Continue Offering Its Present Collegiate Courses and to Offer Other Courses in Sciences and Technology, Amending for the Purpose Section 1 of Republic Act Numbered 3648","orig":"An Act Changing the Name of the Palawan National Agricultural College in the Municipality of Aborlan, Province of Palawan, to State Polytechnic College of Palawan and Authorizing the Same to Continue Offering Its Present Collegiate Courses and to Offer Other Courses in Sciences and Technology, Amending for the Purpose Section 1 of Republic Act Numbered 3648"},"level":"law","status":"active","topics":["education","environment"],"docNumber":"Republic Act No. 8012","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8012_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6491-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The present Palawan National Agricultural College in the Municipality of Aborlan, Province of Palawan, is hereby converted into a state polytechnic college to be known as the State Polytechnic College of Palawan which will offer not only four-year secondary agricultural course, four-year secondary home economics, one-year farm mechanics, and other special courses but also two-year courses leading to the title of associate in agriculture and/or agricultural education and courses leading to the degrees of bachelor of science in agriculture, forestry, and fisheries, bachelor of science in home economics, bachelor of science in agricultural education, master of science (with majors in the different agricultural sciences), and master of agricultural education. It shall also offer courses in arts, sciences and technology, and other related courses as the board of trustees of the state college may deem necessary to carry out its objectives: Provided, That the courses to be offered are consistent with the goals for local, regional and national development."}},{"id":"PH-H6491-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The State Polytechnic College of Palawan is hereby authorized to continue offering its present collegiate courses and to offer other courses in arts, sciences and technology, and other related courses as the Board of Trustees of the state college may deem necessary to carry out its objectives: Provided, That the courses to be offered are consistent with the goals for local, regional and national development."}},{"id":"PH-H6491-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Section 1 of Republic Act No. 3648 which relates to the name of the college is hereby amended accordingly."}},{"id":"PH-H6491-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6492"] = {"id":"PH-H6492","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8013_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Tudela National High School Annex in Poblacion, Municipality of Tudela, Province of Misamis Occidental, From the Kolambutan Bajo National High School in Kolambutan Bajo, Also in the Municipality of Tudela, and Converting It Into An Independent National Comprehensive High School to Be Known as the Tudela National Comprehensive High School, and Appropriating Funds Therefor","orig":"An Act Separating the Tudela National High School Annex in Poblacion, Municipality of Tudela, Province of Misamis Occidental, From the Kolambutan Bajo National High School in Kolambutan Bajo, Also in the Municipality of Tudela, and Converting It Into An Independent National Comprehensive High School to Be Known as the Tudela National Comprehensive High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8013","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8013_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6492-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Tudela National High School Annex in Poblacion, Municipality of Tudela, Province of Misamis Occidental, is hereby separated from the Kolambutan Bajo National High School in Kolambutan Bajo, also in the Municipality of Tudela, and converted into an independent national comprehensive high school, to be known as the Tudela National Comprehensive High School."}},{"id":"PH-H6492-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6492-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, records, assets, and liabilities of the Tudela National High School Annex are hereby transferred to and absorbed by the Tudela National Comprehensive High School."}},{"id":"PH-H6492-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6492-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6493"] = {"id":"PH-H6493","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8014_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Balao Extension High School in Barangay Balao, Barili, Cebu, From the Luhod National High School in Barangay Luhod, and Converting It Into An Independent National High School to Be Known as the Balao National High School, and Appropriating Funds Therefor","orig":"An Act Separating the Balao Extension High School in Barangay Balao, Barili, Cebu, From the Luhod National High School in Barangay Luhod, and Converting It Into An Independent National High School to Be Known as the Balao National High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8014","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8014_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6493-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Balao Extension High School in Barangay Balao, Municipality of Barili, Cebu, is hereby separated from the Luhod National High School in Barangay Luhod, and converted into an independent national high school to be known as the Balao National High School."}},{"id":"PH-H6493-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6493-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"All personnel, assets, liabilities, and records of the Balao Extension High School are hereby transferred to and absorbed by the Balao National High School."}},{"id":"PH-H6493-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6493-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6494"] = {"id":"PH-H6494","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8015_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Separating the Malabog National High School Annex/Extension in Barangay Megkawayan, From the Malabog National High School in Barangay Malabog, Both in Davao City, and Converting It Into a Separate and Independent National High School to Be Known as the Telesforo S. Singson High School, and Appropriating Funds Therefor","orig":"An Act Separating the Malabog National High School Annex/Extension in Barangay Megkawayan, From the Malabog National High School in Barangay Malabog, Both in Davao City, and Converting It Into a Separate and Independent National High School to Be Known as the Telesforo S. Singson High School, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["administrative","education"],"docNumber":"Republic Act No. 8015","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8015_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6494-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Malabog National High School Annex/Extension in Barangay Megkawayan, Davao City, is hereby separated from the Malabog National High School in Barangay Malabog, and converted into a separate and independent national high school to be known as the Telesforo S. Singson High School."}},{"id":"PH-H6494-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Education, Culture and Sports shall issue such rules and regulations as may be necessary to carry out the provisions of this Act."}},{"id":"PH-H6494-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The amount necessary for the implementation of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6494-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6495"] = {"id":"PH-H6495","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8016_1995.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Bohol National High School in Tagbilaran City, Province of Bohol, to Dr. Cecilio Putong National High School","orig":"An Act Changing the Name of the Bohol National High School in Tagbilaran City, Province of Bohol, to Dr. Cecilio Putong National High School"},"level":"law","status":"active","topics":["education"],"docNumber":"Republic Act No. 8016","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8016_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6495-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Bohol National High School in Tagbilaran City, Province of Bohol, is hereby changed to Dr. Cecilio Putong National High School."}},{"id":"PH-H6495-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6496"] = {"id":"PH-H6496","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8017_1995.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the Talisay School of Fisheries in the Municipality of Talisay, Province of Negros Occidental, to Inocencio V. Ferrer Memorial School of Fisheries","orig":"An Act Changing the Name of the Talisay School of Fisheries in the Municipality of Talisay, Province of Negros Occidental, to Inocencio V. Ferrer Memorial School of Fisheries"},"level":"law","status":"active","topics":["environment","education"],"docNumber":"Republic Act No. 8017","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8017_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6496-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Talisay School of Fisheries in the Municipality of Talisay, Province of Negros Occidental, is hereby changed to Inocencio V. Ferrer Memorial School of Fisheries."}},{"id":"PH-H6496-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6497"] = {"id":"PH-H6497","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8018_1995.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Reverting the Name of Philippine Pediatric Hospital and Development Center in Quezon City, to Philippine Children's Medical Center","orig":"An Act Reverting the Name of Philippine Pediatric Hospital and Development Center in Quezon City, to Philippine Children's Medical Center"},"level":"law","status":"active","topics":["civil","health"],"docNumber":"Republic Act No. 8018","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8018_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6497-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The name of the Philippine Pediatric Hospital and Development Center in Quezon Boulevard, Quezon City, is hereby reverted to Philippine Children's Medical Center."}},{"id":"PH-H6497-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Any other law, decree, act, executive order, proclamation, rules and regulations or part thereof inconsistent with any of the provisions of this Act are hereby repealed, amended or modified accordingly."}},{"id":"PH-H6497-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6498"] = {"id":"PH-H6498","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8019_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Upgrading the Eulogio Rodriguez, Sr. Memorial Hospital From a Provincial Hospital to a Medical Center, Renaming It as 'Amang' Rodriguez Medical Center, and Appropriating Funds Therefor","orig":"An Act Upgrading the Eulogio Rodriguez, Sr. Memorial Hospital From a Provincial Hospital to a Medical Center, Renaming It as 'Amang' Rodriguez Medical Center, and Appropriating Funds Therefor"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 8019","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8019_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6498-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The status of the Eulogio Rodriguez, Sr. Memorial Hospital in the Municipality of Marikina, Metro Manila, is hereby upgraded from a provincial hospital to a medical center of the Department of Health. As such, the hospital shall be under the laws, rules and regulations governing the category of existing hospitals."}},{"id":"PH-H6498-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be included in the General Appropriations Act of the year following its enactment into law and thereafter."}},{"id":"PH-H6498-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The hospital as a medical center shall participate in the training of doctors in their chosen field of expertise, nurses and paramedics. The conduct of research shall also be undertaken."}},{"id":"PH-H6498-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Henceforth, this hospital shall be named as 'Amang' Rodriguez Medical Center."}},{"id":"PH-H6498-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect immediately upon its approval and publication in the Official Gazette."}}],"pack":"ph-p92"};
  FT["PH-H6499"] = {"id":"PH-H6499","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8020_1995.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Changing the Name of the National Kidney Institute to National Kidney and Transplant Institute and for Other Purposes","orig":"An Act Changing the Name of the National Kidney Institute to National Kidney and Transplant Institute and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8020","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8020_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6499-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The National Kidney Institute is hereby renamed as the National Kidney and Transplant Institute and shall be designated as the lead center for organ transplantation."}},{"id":"PH-H6499-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6500"] = {"id":"PH-H6500","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8021_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring the Moriones Festival of the Province of Marinduque a Major Tourist Attraction","orig":"An Act Declaring the Moriones Festival of the Province of Marinduque a Major Tourist Attraction"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8021","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8021_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6500-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Moriones Festival of the Province of Marinduque is hereby declared a major tourist attraction. As such, it shall be accorded due recognition and shall become a priority program of the Department of Tourism."}},{"id":"PH-H6500-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government shall, within one (1) year from the approval of this Act, prepare a tourism development and promotion plan for the Moriones Festival. The plan shall provide for the construction and installation of such appropriate facilities and infrastructure as shall encourage tourism in the area and promote the festival as a religious and cultural heritage."}},{"id":"PH-H6500-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development and promotion plan and shall incorporate the same in the Department's overall tourism development program for the ensuing calendar year."}},{"id":"PH-H6500-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall promulgate the necessary rules and regulations for the proper implementation of this Act."}},{"id":"PH-H6500-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6501"] = {"id":"PH-H6501","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8022_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Declaring the Municipalities of Boac, Buenavista, and Torrijos in the Province of Marinduque as Tourist Zones","orig":"An Act Declaring the Municipalities of Boac, Buenavista, and Torrijos in the Province of Marinduque as Tourist Zones"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8022","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8022_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6501-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The municipalities of Boac, Buenavista, and Torrijos are hereby declared as tourist zones. As such, they shall be accorded priority development by the Department of Tourism and shall be subject to the rules and regulations governing the development of tourist zones."}},{"id":"PH-H6501-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government shall, within one (1) year from the approval of this Act, prepare a tourism development plan for the said municipalities of the Province of Marinduque which shall provide for the construction, improvement and/or maintenance of such appropriate facilities and infrastructure as shall enhance tourism in the areas stated in this Act: Provided, That said development plan shall ensure the preservation of the natural beauty and/or historical significance of the area."}},{"id":"PH-H6501-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development plan and shall incorporate the same in its overall tourism development program for the ensuing calendar year."}},{"id":"PH-H6501-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall likewise promulgate the necessary rules and regulations for the proper implementation of this Act."}},{"id":"PH-H6501-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6502"] = {"id":"PH-H6502","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8023_1995.html","fetchedAt":"2026-10-06","articleCount":6,"structureMode":"ARTICLE","title":{"zh":"设立Balo-i市","en":"An Act Declaring the Man-made Lake in the Municipality of Balo-i, Province of Lanao Del Norte, a Tourist Spot","orig":"An Act Declaring the Man-made Lake in the Municipality of Balo-i, Province of Lanao Del Norte, a Tourist Spot"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8023","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 6 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8023_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6502-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The man-made lake in the Municipality of Balo-i, Province of Lanao del Norte, is hereby declared a tourist spot. As such, it shall be accorded priority development by the Department of Tourism and shall be subject to the rules and regulations governing the development of tourist spots."}},{"id":"PH-H6502-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government shall, within one (1) year from the approval of this Act, prepare a tourism development plan which shall provide for the construction, improvement and/or maintenance of such appropriate facilities and infrastructure as shall encourage tourism in the area: Provided, That said development plan shall ensure the preservation of the natural beauty and/or historical significance thereof."}},{"id":"PH-H6502-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development plan and shall incorporate the same in its overall tourism development program for the ensuing calendar year."}},{"id":"PH-H6502-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall likewise promulgate the necessary rules and regulations for the proper implementation of this Act."}},{"id":"PH-H6502-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Any law which is inconsistent with any provision of this Act is hereby repealed or modified accordingly."}},{"id":"PH-H6502-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6503"] = {"id":"PH-H6503","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8024_1995.html","fetchedAt":"2026-10-06","articleCount":5,"structureMode":"ARTICLE","title":{"zh":"设立Babatngon市","en":"An Act Declaring Busay Falls in the Municipality of Babatngon, Province of Leyte, a Tourist Spot","orig":"An Act Declaring Busay Falls in the Municipality of Babatngon, Province of Leyte, a Tourist Spot"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8024","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 5 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8024_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6503-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Busay Falls, located in the Municipality of Babatngon, Province of Leyte, is hereby declared a tourist spot. As such, it shall be accorded priority development by the Department of Tourism, subject to the rules and regulations governing the development of tourist spots."}},{"id":"PH-H6503-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The Department of Tourism, in coordination with the Philippine Tourism Authority and other concerned agencies of the government shall, within one (1) year from the approval of this Act, prepare a development plan involving the construction, installation and maintenance of such appropriate facilities and infrastructure as shall enhance tourism in the area: Provided, That said development plan shall ensure the preservation of the natural beauty and historical significance thereof."}},{"id":"PH-H6503-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Department of Tourism shall take immediate steps to implement said development plan and shall incorporate the same in the Department's overall tourism development program for the year following the approval of this Act."}},{"id":"PH-H6503-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The Department of Tourism shall promulgate the necessary rules and regulations for the proper implementation of this Act."}},{"id":"PH-H6503-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6504"] = {"id":"PH-H6504","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8025_1995.html","fetchedAt":"2026-10-06","articleCount":11,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting the Golden Broadcast Professional, Inc., a Franchise to Construct, Maintain and Operate a Station for Fm Radio and Television Broadcasting in the Island of Mindanao","orig":"An Act Granting the Golden Broadcast Professional, Inc., a Franchise to Construct, Maintain and Operate a Station for Fm Radio and Television Broadcasting in the Island of Mindanao"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8025","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 11 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8025_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6504-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Subject to the provisions of the Constitution, Act Numbered Thirty-eight hundred and forty-six, entitled \"An Act Providing for the Regulation of Radio Stations and Communications in the Philippine Islands, and for Other Purposes,\" Act Numbered Thirty-nine hundred and ninety-seven known as the Radio Broadcasting Law, and Commonwealth Act Numbered One hundred and forty-six known as the Public Service Act, and their amendments, the Golden Broadcast Professional, Inc., hereinafter referred to as the \"grantee,\" is hereby granted a franchise for a period of twenty-five (25) years from the approval of this Act, to construct, maintain and operate for commercial purposes and in the public interest, a station for FM radio and television broadcasting in the island of Mindanao, Republic of the Philippines, at such place as the grantee may select and the National Telecommunications Commission may approve."}},{"id":"PH-H6504-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The grantee shall file a bond in the amount of Fifty thousand pesos (P50,000) to guarantee the full compliance and fulfillment of the conditions under which this franchise is granted. If after four (4) years from the date of the approval of this Act, the grantee shall have fulfilled said conditions, or soon thereafter, the aforesaid bond shall be cancelled by the Philippine Government, otherwise, it shall be forfeited in favor of the State."}},{"id":"PH-H6504-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"A special right is hereby reserved to the President of the Philippines, in times of war, rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to take over and operate the said station or to authorize the temporary use and operation thereof by any department of the government upon due compensation to the grantee for the use of said station during the period when they shall be so operated."}},{"id":"PH-H6504-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The President of the Philippines shall have the power and authority to permit the construction of said station upon such terms and conditions as he may prescribe."}},{"id":"PH-H6504-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the event of any individual, partnership or corporation receiving from the Congress of the Philippines a similar franchise in which there shall be any term more favorable than that granted herein or tending to place the herein grantee at any disadvantage, then such term or terms shall ipso facto form part of the terms hereof and shall operate equally in favor of the grantee as in the case of said competing individual, partnership or corporation."}},{"id":"PH-H6504-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The grantee shall not require any prior censorship in any speech, play or other matter to be broadcast from its station: Provided, That the grantee, during any broadcast, may cut off from the air the speech, play or other matter being broadcast if the tendency thereof is to propose and/or incite treason, rebellion or sedition, or the language used therein or the theme thereof is indecent or immoral and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6504-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(a) The franchise shall not take effect nor shall any power thereunder be exercised by the grantee until the National Telecommunications Commission shall have allotted to the grantee the frequencies, wavelengths and channels to be used thereunder, have determined the stations to and from which frequency and wavelength may be used, and have issued to the grantee a license for such use.\n(b) The National Telecommunications Commission on reasonable notice to the grantee, may at any time change or modify, in whole or in part, any or all of the allotments of frequencies or wavelengths to be used. It may take such actions whenever in its judgment:\n1. Such frequencies and wavelengths have been used, or there is danger that they will be used by the grantee to impair of stifle competition, or to obtain a monopoly in electrical communication, or to secure unreasonable rates for such communications, or to violate otherwise the laws of public policy of the Republic of the Philippines.\n2. The public interests require that such frequencies and wavelengths should be used for purposes other than those of the grantee, either by the government of the Republic of the Philippines or by other individuals or other corporations licensed by it; and\n3. For any reason, the public interest so requires."}},{"id":"PH-H6504-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The grantee shall hold the national, provincial, city and municipal governments of the Republic of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or persons, caused by the construction or operation of the station of the grantee."}},{"id":"PH-H6504-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"No private property shall be taken for any purpose by the grantee without proper condemnation proceeding and just compensation paid and tendered therefor, and any authority to take and occupy land contained herein shall not apply to the taking, use or actual and necessary purpose, for which the franchise is granted."}},{"id":"PH-H6504-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"The grantee shall not lease, transfer, grant the usufruct of, sell or assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other legal entity nor merge with any other company or corporation organized for the same purpose, without the previous approval of the Congress of the Philippines. Any corporation to which this franchise may be sold, transferred or assigned shall be subject to the corporation laws of the Philippines now existing or hereafter enacted, and any person, firm, company, corporation or other commercial or legal entity to which this franchise is sold, transferred or assigned shall be subject to all conditions, terms, restrictions and limitations of this Act as fully and completely and to the same extent as if the franchise has been originally granted to the said person, firm, company, corporation or other commercial or legal entity."}},{"id":"PH-H6504-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6505"] = {"id":"PH-H6505","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8026_1995.html","fetchedAt":"2026-10-06","articleCount":15,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting the Beta Broadcasting System Corporation a Franchise to Construct, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon, and for Other Purposes","orig":"An Act Granting the Beta Broadcasting System Corporation a Franchise to Construct, Operate and Maintain Radio Broadcasting Stations in the Island of Luzon, and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8026","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 15 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8026_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6505-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Beta Broadcasting System Corporation, its successors or assigns and hereunder referred to as the grantee, a franchise to construct, install, operate and maintain for commercial purposes and in the public interest, radio broadcasting stations in the Island of Luzon, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantee's private use in its broadcast services."}},{"id":"PH-H6505-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing station or stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantee's services and/or the availability thereof."}},{"id":"PH-H6505-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6505-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene; or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest; or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6505-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security, and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations or facilities during the period when they shall be so operated."}},{"id":"PH-H6505-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of the approval of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6505-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - This franchise shall become effective upon acceptance in writing by the grantee. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Nonacceptance shall render the franchise void."}},{"id":"PH-H6505-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay a franchise tax at such percentage as may be prescribed by law on all gross receipts of the radio business transacted under this franchise by the grantee, its successors or assigns: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72 unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representative, in accordance with the National Internal Revenue Code, and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6505-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast from its stations: Provided, That the grantee, during any broadcast shall cut off from the air the speech, play, act or scene, or other matter being broadcast if the tendency thereof is to propose and/ or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6505-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines free from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6505-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person, firm, company, corporation or other commercial or legal entity, nor shall the controlling interest of the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred, or assigned, shall be subject to all the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6505-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"General Broadcast Policy Law. - The grantee shall comply with a general broadcast policy law which Congress may hereafter enact."}},{"id":"PH-H6505-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6505-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6505-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Effectivity Clause. - This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6506"] = {"id":"PH-H6506","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8027_1995.html","fetchedAt":"2026-10-06","articleCount":14,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Granting a Franchise to the Kaissar Broadcasting Network, Inc. (KBNI), to Construct, Install, Establish, Operate, Manage and Maintain a Network of Radio and Television Stations Any Where in the Philippines, and for Other Purposes","orig":"An Act Granting a Franchise to the Kaissar Broadcasting Network, Inc. (KBNI), to Construct, Install, Establish, Operate, Manage and Maintain a Network of Radio and Television Stations Any Where in the Philippines, and for Other Purposes"},"level":"law","status":"active","topics":["investment"],"docNumber":"Republic Act No. 8027","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-05-25","completenessNote":"全文，共 14 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8027_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6506-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Nature and Scope of Franchise. - Subject to the provisions of the Constitution and applicable laws, rules and regulations, there is hereby granted to the Kaissar Broadcasting Network, Inc. (KBNI), hereunder referred to as the grantee, its successors or assigns, a franchise to construct, install, establish, operate, manage and maintain for commercial purposes and in the public interest, radio and/or television broadcasting stations anywhere in the Philippines, with the corresponding technological auxiliaries or facilities, special broadcast and other program and distribution services and relay stations, and to install radio communication facilities for the grantees private use in its broadcast services."}},{"id":"PH-H6506-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Manner of Operation of Stations or Facilities. - The stations or facilities of the grantee shall be constructed and operated in a manner as will at most result only in the minimum interference on the wavelengths or frequencies of the other existing station or stations which may be established by law, without in any way diminishing its own right to use its selected wavelengths or frequencies and the quality of transmission or reception thereon as should maximize rendition of the grantees service and/or the availability thereof."}},{"id":"PH-H6506-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Prior Approval of the National Telecommunications Commission. - The grantee shall secure from the National Telecommunications Commission the appropriate permits and licenses for its stations and shall not use any frequency in the radio/television spectrum without having been authorized by the Commission. The Commission, however, shall not unreasonably withhold or delay the grant of any such authority."}},{"id":"PH-H6506-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Responsibility to the Public. - The grantee shall provide adequate public service time to enable the government, through the said broadcasting stations, to reach the population on important public issues; provide at all times sound and balanced programming; assist in the functions of public information and education; conform to the ethics of honest enterprise; and not use its stations for the broadcasting of obscene and indecent language, speech, act or scene, or for the dissemination of deliberately false information or willful misrepresentation to the detriment of the public interest, or to incite, encourage, or assist in subversive or treasonable acts."}},{"id":"PH-H6506-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Right of Government. - A special right is hereby reserved to the President of the Philippines, in times of rebellion, public peril, calamity, emergency, disaster or disturbance of peace and order, to temporarily take over and operate the stations of the grantee, to temporarily suspend the operation of any station in the interest of public safety, security and public welfare, or to authorize the temporary use and operation thereof by any agency of the government, upon due compensation to the grantee, for the use of said stations during the period when they shall be so operated."}},{"id":"PH-H6506-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Term of Franchise. - This franchise shall be for a term of twenty-five (25) years from the date of approval of this Act, unless sooner revoked or cancelled. In the event the grantee fails to operate continuously for two (2) years, this franchise shall be deemed ipso facto revoked."}},{"id":"PH-H6506-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Acceptance and Compliance. - Acceptance of this franchise shall be given in writing within sixty (60) days after approval of this Act. Upon giving such acceptance, the grantee shall exercise the privileges granted under this Act. Non-acceptance shall render the franchise void."}},{"id":"PH-H6506-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"Tax Provisions. - The grantee, its successors or assigns, shall be liable to pay the same taxes on their real estate, buildings and personal property, exclusive of this franchise, as other persons or corporations are now or hereafter may be required by law to pay. In addition thereto, the grantee, its successors or assigns, shall pay a franchise tax equivalent to three percent (3%) of all gross receipts of the radio and television business transacted under this franchise by the grantee, its successors or assigns, and the said percentage shall be in lieu of all taxes on this franchise or earnings thereof: Provided, That the grantee, its successors or assigns, shall continue to be liable for income taxes payable under Title II of the National Internal Revenue Code pursuant to Section 2 of Executive Order No. 72, unless the latter enactment is amended or repealed, in which case the amendment or repeal shall be applicable thereto.\nThe grantee shall file the return with and pay the tax due thereon to the Commissioner of Internal Revenue or his duly authorized representatives in accordance with the National Internal Revenue Code and the return shall be subject to audit by the Bureau of Internal Revenue."}},{"id":"PH-H6506-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"Self-regulation by and Undertaking of Grantee. - The grantee shall not require any previous censorship of any speech, play, act or scene, or other matter to be broadcast and/or telecast from its stations: Provided, That the grantee, during any broadcast and/or telecast, shall cut off from the air the speech, play, act or scene, or other matter being broadcast/telecast if the tendency thereof is to propose and/or incite treason, rebellion or sedition; or the language used therein or the theme thereof is indecent or immoral, and willful failure to do so shall constitute a valid cause for the cancellation of this franchise."}},{"id":"PH-H6506-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Warranty in Favor of National and Local Governments. - The grantee shall hold the national, provincial, and municipal governments of the Philippines harmless from all claims, accounts, demands or actions arising out of accidents or injuries, whether to property or to persons, caused by the construction or operation of the stations of the grantee."}},{"id":"PH-H6506-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Sale, Lease, Transfer, Usufruct, etc. - The grantee shall not lease, transfer, grant the usufruct of, sell nor assign this franchise or the rights and privileges acquired thereunder to any person firm, company, corporation or other commercial or legal entity, nor shall the controlling interest in the grantee be transferred to any such private person, firm, company, corporation or entity without the prior approval of the Congress of the Philippines. Any person or entity to which this franchise is sold, transferred or assigned, shall be subject to all the same conditions, terms, restrictions, and limitations of this Act."}},{"id":"PH-H6506-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Separability Clause. - If any of the sections or provisions of this Act is held invalid, all the other provisions not affected thereby shall remain valid."}},{"id":"PH-H6506-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Repealability and Nonexclusivity Clause. - This franchise shall be subject to amendment, alteration, or repeal by the Congress of the Philippines when the public interest so requires and shall not be interpreted as an exclusive grant of the privileges herein provided for."}},{"id":"PH-H6506-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Effectivity Clause. - This Act shall take effect fifteen (15) days from the date of its publication in at least two (2) newspapers of general circulation in the Philippines."}}],"pack":"ph-p92"};
  FT["PH-H6507"] = {"id":"PH-H6507","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8028_1995.html","fetchedAt":"2026-10-06","articleCount":2,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Naming the Road From Tigbao (Tacloban) to Sta. Fe, Pastrana, Dagami and Tanauan, Province of Leyte, as Filomeno Montejo Highway","orig":"An Act Naming the Road From Tigbao (Tacloban) to Sta. Fe, Pastrana, Dagami and Tanauan, Province of Leyte, as Filomeno Montejo Highway"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8028","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-06-05","completenessNote":"全文，共 2 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8028_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6507-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The road starting from Tigbao (Tacloban) to Sta. Fe, Pastrana, Dagami and Tanauan (Junction of Pan-Philippine Highway), Province of Leyte, shall be known as the Filomeno Montejo Highway."}},{"id":"PH-H6507-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6508"] = {"id":"PH-H6508","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8029_1995.html","fetchedAt":"2026-10-06","articleCount":3,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Renaming the Taytay Bridge Linking Tagbilaran City With Panglao Island in the Province of Bohol to Ambassador Jacinto Castel Borja Bridge, and for Other Purposes","orig":"An Act Renaming the Taytay Bridge Linking Tagbilaran City With Panglao Island in the Province of Bohol to Ambassador Jacinto Castel Borja Bridge, and for Other Purposes"},"level":"law","status":"active","topics":["general"],"docNumber":"Republic Act No. 8029","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-06-05","completenessNote":"全文，共 3 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8029_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6508-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"Ambassador Jacinto Castel Borja was the first and only Boholano to serve as Philippine envoy to the United Nations. He also served as a provincial governor of Bohol from 1952 to 1955."}},{"id":"PH-H6508-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"To perpetuate his memory, the Taytay Bridge which links Tagbilaran City with Panglao Island in the Province of Bohol is hereby renamed Ambassador Jacinto Castel Borja Bridge."}},{"id":"PH-H6508-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p92"};
  FT["PH-H6509"] = {"id":"PH-H6509","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1995/ra_8030_1995.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":null,"en":"An Act Altering Substantially the Boundaries And/Or Transferring the Territorial Jurisdiction of Barangay Popolon From the Municipality of Bongabon to the City of Palayan, Province of Nueva Ecija, Exercising Administrative Control and Supervision Over the Said Barangay and for Other Purposes","orig":"An Act Altering Substantially the Boundaries And/Or Transferring the Territorial Jurisdiction of Barangay Popolon From the Municipality of Bongabon to the City of Palayan, Province of Nueva Ecija, Exercising Administrative Control and Supervision Over the Said Barangay and for Other Purposes"},"level":"law","status":"active","topics":["administrative"],"docNumber":"Republic Act No. 8030","issuingBody":"Congress of the Philippines","promulgatedDate":"1995-06-05","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1995/ra_8030_1995.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H6509-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"The Congress of the Philippines hereby alters substantially the boundaries of the Municipality of Bongabon and the City of Palayan in the Province of Nueva Ecija, by transferring the territory of Barangay Popolon from the Municipality of Bongabon to the City of Palayan for economic convenience and governance."}},{"id":"PH-H6509-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The City of Palayan shall acquire territorial jurisdiction and administrative control and supervision over the said barangay upon the approval of this Act by a majority of the votes cast in the plebiscite called for such purpose."}},{"id":"PH-H6509-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The chairman of the Commission on Elections is hereby mandated to conduct a plebiscite in the abovementioned local government units directly affected within one hundred twenty (120) days immediately after the effectivity of this Act."}},{"id":"PH-H6509-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect immediately upon its approval."}}],"pack":"ph-p92"};
